 * Longest common subsequence between `base` and `side` (arrays of strings),
 * with a deterministic tie-break for equal-length subsequences: walking both
 * documents from the start, take a match whenever the current lines are
 * equal, and otherwise advance the side whose remaining LCS length is at
 * least as long as the other's, preferring to advance the base on a tie.
 *
 * Returns the list of `[baseIndex, sideIndex]` matched pairs, in order.
 */
export function lcsMatches(base, side) {
  const m = base.length
  const n = side.length
  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Array(n + 1).fill(0)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Turn a list of matches into the list of changes: each change replaces a
 * run of base lines `[baseStart, baseEnd)` with a run of `side`'s lines.
 */
export function changesFromMatches(base, side, matches) {
  const changes = []
  let baseStart = 0
  let sideStart = 0
  for (const [bi, si] of matches) {
    if (bi > baseStart || si > sideStart) {
      changes.push({ baseStart, baseEnd: bi, lines: side.slice(sideStart, si) })
    }
    baseStart = bi + 1
    sideStart = si + 1
  }
  if (baseStart < base.length || sideStart < side.length) {
    changes.push({ baseStart, baseEnd: base.length, lines: side.slice(sideStart, side.length) })
  }
  return changes
}

export function diff(base, side) {
  const matches = lcsMatches(base, side)
  return changesFromMatches(base, side, matches)
}
"}

