    k++
    while (k < tagged.length && tagged[k].baseStart <= end) {
      end = Math.max(end, tagged[k].baseEnd)
      changes.push(tagged[k])
      k++
    }
    if (start > pos) {
      regions.push({ stable: true, baseStart: pos, baseEnd: start })
    }
    regions.push({ stable: false, baseStart: start, baseEnd: end, changes })
    pos = end
  }
  if (pos < base.length) {
    regions.push({ stable: true, baseStart: pos, baseEnd: base.length })
  }
  return regions
}

