 * that side's own changes (and before/after them) with the unchanged base
 * lines. */
function buildSide(base, changes, start, end) {
  const result = []
  let pos = start
  for (const c of changes) {
    result.push(...base.slice(pos, c.baseStart))
    result.push(...c.lines)
    pos = c.baseEnd
  }
  result.push(...base.slice(pos, end))
  return result
