 * Compute the full list of regions with their resolutions for `merge`,
 * `merge2` and `regions` to share.
 *
 * Each region is one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = diff(base, mine)
  const theirsChanges = diff(base, theirs)
  const regions = buildRegions(base, mineChanges, theirsChanges)

  return regions.map(region => {
    if (region.stable) {
      return { kind: 'stable', lines: base.slice(region.baseStart, region.baseEnd) }
    }
    const mineOwn = region.changes.filter(c => c.side === 'mine')
    const theirsOwn = region.changes.filter(c => c.side === 'theirs')
